const storageKey = 'domain-dictionary-groups';

export function loadDomainDictionaries(): DomainDictionaryGroup[] {
  const defaults = defaultDomainDictionaries.map(group => ({ ...group, words: [...group.words] }));
  try {
    const saved = JSON.parse(localStorage.getItem(storageKey) || 'null');
    if (Array.isArray(saved) && saved.length) {
      const savedGroups = saved as DomainDictionaryGroup[];
      const merged = defaults.map(group => {
        const existing = savedGroups.find(item => item.id === group.id);
        return existing
          ? { ...group, ...existing, words: [...new Set([...group.words, ...(existing.words || [])])] }
          : group;
      });
      const custom = savedGroups.filter(item => !defaults.some(group => group.id === item.id));
      return [...merged, ...custom.map(group => ({ ...group, words: [...group.words] }))];
    }
  } catch {
    /* use defaults */
  }
  return defaults;
}

export function saveDomainDictionaries(groups: DomainDictionaryGroup[]) {
  localStorage.setItem(storageKey, JSON.stringify(groups));
}
